const unsigned short CONFIG_PORT_ADDR = 0x0CF8;
const unsigned short CONFIG_PORT_DATA = 0x0CFC;
const unsigned int WRITE_VALUE = 0x8000AABB;

// Prerequisite: Enable port access (iopl(3) or ioperm())
// ioperm(CONFIG_PORT_ADDR, 8, 1);

// Write 32-bit value immediately
outl(WRITE_VALUE, CONFIG_PORT_ADDR);

// Write 32-bit value, wait/pause for I/O completion
outl_p(0xDEADBEEF, CONFIG_PORT_DATA);

// Kernel/User API:
// void outl(unsigned int value, unsigned short port);
// void outl_p(unsigned int value, unsigned short port);
// (Requires <sys/io.h> for userspace)
